-- ShopBill PostgreSQL backend schema
-- Target: PostgreSQL 16+
-- Source-aligned: PRD, TRD, APPFLOW and UI/UX specification v1.0 (2026-10-26)
-- IDs are generated by the API as UUIDv7. Do not replace this with random UUIDs.
-- Money is integer paise; rates are basis points; quantities are thousandths.
-- Apply through Alembic migrations in production; this file is a baseline reference.

BEGIN;

-- ---------------------------------------------------------------------------
-- Enumerations
-- ---------------------------------------------------------------------------
CREATE TYPE shop_status AS ENUM ('ACTIVE', 'SUSPENDED', 'CLOSED');
CREATE TYPE tax_scheme AS ENUM ('REGULAR', 'COMPOSITION', 'UNREGISTERED');
CREATE TYPE membership_status AS ENUM ('INVITED', 'ACTIVE', 'SUSPENDED', 'REVOKED');
CREATE TYPE party_kind AS ENUM ('CUSTOMER', 'SUPPLIER', 'BOTH');
CREATE TYPE tax_treatment AS ENUM ('TAXABLE', 'EXEMPT', 'NIL_RATED', 'NON_GST');
CREATE TYPE document_type AS ENUM ('TAX_INVOICE', 'BILL_OF_SUPPLY', 'CREDIT_NOTE', 'DEBIT_NOTE', 'SALES_RETURN', 'PURCHASE_BILL', 'QUOTATION', 'DELIVERY_CHALLAN');
CREATE TYPE document_status AS ENUM ('DRAFT', 'FINALIZED', 'CANCELLED', 'CONVERTED', 'EXPIRED');
CREATE TYPE payment_mode AS ENUM ('CASH', 'UPI', 'CARD', 'CHEQUE', 'BANK_TRANSFER', 'CREDIT', 'OTHER');
CREATE TYPE payment_purpose AS ENUM ('SALE_TENDER', 'CUSTOMER_RECEIPT', 'SUPPLIER_PAYMENT', 'CASH_REFUND', 'UPI_REFUND', 'PURCHASE_PAYMENT', 'OTHER');
CREATE TYPE ledger_side AS ENUM ('DEBIT', 'CREDIT');
CREATE TYPE stock_movement_type AS ENUM ('OPENING_STOCK', 'PURCHASE_INWARD', 'SALE', 'SALES_RETURN_RESTOCK', 'SALES_RETURN_DAMAGED', 'STOCK_ADJUSTMENT', 'PURCHASE_RETURN', 'CANCELLATION_REVERSAL', 'TRANSFER_IN', 'TRANSFER_OUT');
CREATE TYPE purchase_status AS ENUM ('DRAFT', 'POSTED', 'CANCELLED');
CREATE TYPE backup_status AS ENUM ('UPLOADING', 'AVAILABLE', 'FAILED', 'DELETED', 'EXPIRED');
CREATE TYPE sync_bundle_status AS ENUM ('RECEIVED', 'APPLIED', 'REJECTED', 'PARTIALLY_APPLIED');
CREATE TYPE report_job_status AS ENUM ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED');
CREATE TYPE report_format AS ENUM ('XLSX', 'CSV', 'PDF', 'JSON', 'XML');
CREATE TYPE worker_job_status AS ENUM ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'DEAD_LETTER');
CREATE TYPE message_channel AS ENUM ('WHATSAPP', 'SMS', 'EMAIL');
CREATE TYPE message_status AS ENUM ('QUEUED', 'SENDING', 'SENT', 'DELIVERED', 'FAILED', 'CANCELLED');
CREATE TYPE consent_status AS ENUM ('GRANTED', 'REVOKED');
CREATE TYPE data_request_type AS ENUM ('EXPORT', 'ERASURE');
CREATE TYPE data_request_status AS ENUM ('PENDING', 'PROCESSING', 'COMPLETED', 'REJECTED', 'FAILED');
CREATE TYPE compliance_kind AS ENUM ('E_INVOICE', 'E_WAY_BILL');
CREATE TYPE compliance_status AS ENUM ('DRAFT', 'SUBMITTED', 'ACCEPTED', 'REJECTED', 'CANCELLED', 'FAILED');

-- ---------------------------------------------------------------------------
-- Global / reference data
-- ---------------------------------------------------------------------------
CREATE TABLE states (
    code char(2) PRIMARY KEY,
    name text NOT NULL,
    is_union_territory boolean NOT NULL DEFAULT false,
    active boolean NOT NULL DEFAULT true
);

CREATE TABLE gst_rates (
    id uuid PRIMARY KEY,
    tax_code text NOT NULL,
    rate_bps integer NOT NULL CHECK (rate_bps BETWEEN 0 AND 10000),
    cess_rate_bps integer NOT NULL DEFAULT 0 CHECK (cess_rate_bps BETWEEN 0 AND 10000),
    effective_from date NOT NULL,
    effective_to date,
    source_label text,
    reference_bundle_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (effective_to IS NULL OR effective_to >= effective_from),
    UNIQUE (tax_code, rate_bps, cess_rate_bps, effective_from)
);
CREATE INDEX ix_gst_rates_effective ON gst_rates (effective_from, effective_to);

CREATE TABLE hsn_codes (
    code varchar(8) PRIMARY KEY,
    description text NOT NULL,
    recommended_tax_code text,
    minimum_digits smallint NOT NULL DEFAULT 4 CHECK (minimum_digits BETWEEN 2 AND 8),
    effective_from date NOT NULL,
    effective_to date,
    reference_bundle_version text NOT NULL,
    active boolean NOT NULL DEFAULT true,
    CHECK (effective_to IS NULL OR effective_to >= effective_from)
);
CREATE INDEX ix_hsn_codes_description ON hsn_codes USING gin (to_tsvector('simple', description));

CREATE TABLE reference_bundles (
    id uuid PRIMARY KEY,
    bundle_key text NOT NULL,
    version text NOT NULL,
    effective_at timestamptz NOT NULL,
    payload_object_key text NOT NULL,
    sha256 bytea NOT NULL CHECK (octet_length(sha256) = 32),
    signature bytea NOT NULL,
    signature_key_id text NOT NULL,
    etag text NOT NULL,
    published_at timestamptz NOT NULL,
    revoked_at timestamptz,
    UNIQUE (bundle_key, version),
    UNIQUE (bundle_key, etag)
);

-- ---------------------------------------------------------------------------
-- Identity, tenants, memberships, RBAC, devices and authentication lifecycle
-- ---------------------------------------------------------------------------
CREATE TABLE users (
    id uuid PRIMARY KEY,
    email text,
    phone_e164 varchar(20),
    full_name text NOT NULL,
    password_hash text,
    is_platform_admin boolean NOT NULL DEFAULT false,
    is_active boolean NOT NULL DEFAULT true,
    email_verified_at timestamptz,
    phone_verified_at timestamptz,
    last_login_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (email IS NOT NULL OR phone_e164 IS NOT NULL)
);
CREATE UNIQUE INDEX uq_users_email_ci ON users (lower(email)) WHERE email IS NOT NULL;
CREATE UNIQUE INDEX uq_users_phone ON users (phone_e164) WHERE phone_e164 IS NOT NULL;

CREATE TABLE shops (
    id uuid PRIMARY KEY,
    owner_user_id uuid REFERENCES users(id),
    name text NOT NULL,
    legal_name text,
    phone_e164 varchar(20),
    contact_email text,
    address jsonb NOT NULL DEFAULT '{}'::jsonb,
    state_code char(2) REFERENCES states(code),
    gstin varchar(15),
    tax_scheme tax_scheme NOT NULL DEFAULT 'UNREGISTERED',
    financial_year_start_month smallint NOT NULL DEFAULT 4 CHECK (financial_year_start_month BETWEEN 1 AND 12),
    invoice_prefix varchar(16) NOT NULL DEFAULT 'SB/',
    upi_id text,
    preferred_language varchar(5) NOT NULL DEFAULT 'en' CHECK (preferred_language IN ('en', 'hi', 'bn')),
    timezone text NOT NULL DEFAULT 'Asia/Kolkata',
    logo_object_key text,
    demo_mode boolean NOT NULL DEFAULT false,
    status shop_status NOT NULL DEFAULT 'ACTIVE',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id),
    CHECK (gstin IS NULL OR length(gstin) = 15),
    CHECK (tax_scheme = 'UNREGISTERED' OR gstin IS NOT NULL)
);

CREATE TABLE roles (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    code text NOT NULL,
    name text NOT NULL,
    description text,
    is_system_role boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, code)
);

CREATE TABLE permission_catalog (
    code text PRIMARY KEY,
    description text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE role_permissions (
    shop_id uuid NOT NULL,
    role_id uuid NOT NULL,
    permission_code text NOT NULL REFERENCES permission_catalog(code),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (shop_id, role_id, permission_code),
    FOREIGN KEY (shop_id, role_id) REFERENCES roles(shop_id, id) ON DELETE CASCADE
);

CREATE TABLE shop_memberships (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES users(id),
    role_id uuid NOT NULL,
    status membership_status NOT NULL DEFAULT 'ACTIVE',
    invited_by_user_id uuid REFERENCES users(id),
    invited_at timestamptz,
    joined_at timestamptz,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, user_id),
    FOREIGN KEY (shop_id, role_id) REFERENCES roles(shop_id, id)
);

CREATE TABLE shop_locations (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    name text NOT NULL,
    address jsonb NOT NULL DEFAULT '{}'::jsonb,
    state_code char(2) REFERENCES states(code),
    is_default boolean NOT NULL DEFAULT false,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, name)
);
CREATE UNIQUE INDEX uq_shop_default_location ON shop_locations (shop_id) WHERE is_default;

CREATE TABLE devices (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES users(id),
    location_id uuid,
    device_name text NOT NULL,
    platform text NOT NULL CHECK (platform IN ('ANDROID', 'WINDOWS', 'IOS', 'MACOS', 'LINUX', 'OTHER')),
    series_prefix varchar(8) NOT NULL,
    last_seen_at timestamptz,
    last_pulled_cursor bigint NOT NULL DEFAULT 0 CHECK (last_pulled_cursor >= 0),
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, series_prefix),
    FOREIGN KEY (shop_id, location_id) REFERENCES shop_locations(shop_id, id)
);

CREATE TABLE refresh_token_families (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES users(id),
    device_id uuid NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    revoked_at timestamptz,
    revoke_reason text,
    UNIQUE (shop_id, id),
    FOREIGN KEY (shop_id, device_id) REFERENCES devices(shop_id, id)
);

CREATE TABLE refresh_tokens (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    family_id uuid NOT NULL,
    token_hash bytea NOT NULL UNIQUE,
    issued_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    consumed_at timestamptz,
    replaced_by_token_id uuid REFERENCES refresh_tokens(id),
    revoked_at timestamptz,
    UNIQUE (shop_id, id),
    FOREIGN KEY (shop_id, family_id) REFERENCES refresh_token_families(shop_id, id),
    CHECK (expires_at > issued_at)
);
CREATE INDEX ix_refresh_tokens_family ON refresh_tokens (shop_id, family_id, issued_at DESC);

CREATE TABLE login_attempts (
    id uuid PRIMARY KEY,
    normalized_login_hash bytea NOT NULL,
    source_ip inet,
    attempted_at timestamptz NOT NULL DEFAULT now(),
    succeeded boolean NOT NULL,
    lockout_until timestamptz,
    failure_code text
);
CREATE INDEX ix_login_attempts_login_time ON login_attempts (normalized_login_hash, attempted_at DESC);
CREATE INDEX ix_login_attempts_ip_time ON login_attempts (source_ip, attempted_at DESC);

-- Used for replaying idempotent writes. Access must be restricted to the API service;
-- scope_key is constructed by the server (tenant + principal or auth-flow scope).
CREATE TABLE api_idempotency_records (
    id uuid PRIMARY KEY,
    shop_id uuid REFERENCES shops(id) ON DELETE CASCADE,
    scope_key text NOT NULL,
    idempotency_key varchar(255) NOT NULL,
    request_sha256 bytea NOT NULL CHECK (octet_length(request_sha256) = 32),
    response_status smallint NOT NULL,
    response_body jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    UNIQUE (scope_key, idempotency_key),
    CHECK (expires_at > created_at)
);
CREATE INDEX ix_idempotency_expiry ON api_idempotency_records (expires_at);

-- ---------------------------------------------------------------------------
-- Product catalogue and pricing
-- ---------------------------------------------------------------------------
CREATE TABLE product_categories (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    name text NOT NULL,
    parent_id uuid,
    archived_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, name),
    FOREIGN KEY (shop_id, parent_id) REFERENCES product_categories(shop_id, id)
);

CREATE TABLE brands (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    name text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, name)
);

CREATE TABLE units (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    code varchar(12) NOT NULL,
    label text NOT NULL,
    precision_digits smallint NOT NULL DEFAULT 0 CHECK (precision_digits BETWEEN 0 AND 3),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, code)
);

CREATE TABLE products (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    category_id uuid,
    brand_id uuid,
    unit_id uuid NOT NULL,
    sku varchar(100) NOT NULL,
    name text NOT NULL,
    local_name text,
    name_norm text NOT NULL,
    hsn_code varchar(8) REFERENCES hsn_codes(code),
    tax_treatment tax_treatment NOT NULL DEFAULT 'TAXABLE',
    gst_rate_bps integer NOT NULL DEFAULT 0 CHECK (gst_rate_bps BETWEEN 0 AND 10000),
    cess_rate_bps integer NOT NULL DEFAULT 0 CHECK (cess_rate_bps BETWEEN 0 AND 10000),
    mrp_paise bigint CHECK (mrp_paise IS NULL OR mrp_paise >= 0),
    selling_price_paise bigint NOT NULL CHECK (selling_price_paise >= 0),
    purchase_price_paise bigint CHECK (purchase_price_paise IS NULL OR purchase_price_paise >= 0),
    tax_inclusive boolean NOT NULL DEFAULT true,
    min_stock_qty_milli bigint NOT NULL DEFAULT 0 CHECK (min_stock_qty_milli >= 0),
    image_object_key text,
    is_archived boolean NOT NULL DEFAULT false,
    hlc_physical_ms bigint NOT NULL DEFAULT 0,
    hlc_counter integer NOT NULL DEFAULT 0 CHECK (hlc_counter >= 0),
    hlc_node_id uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, sku),
    FOREIGN KEY (shop_id, category_id) REFERENCES product_categories(shop_id, id),
    FOREIGN KEY (shop_id, brand_id) REFERENCES brands(shop_id, id),
    FOREIGN KEY (shop_id, unit_id) REFERENCES units(shop_id, id)
);
CREATE INDEX ix_products_search ON products USING gin (to_tsvector('simple', name_norm));
CREATE INDEX ix_products_category ON products (shop_id, category_id) WHERE NOT is_archived;
CREATE INDEX ix_products_updated ON products (shop_id, updated_at DESC);

CREATE TABLE product_barcodes (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    product_id uuid NOT NULL,
    barcode varchar(128) NOT NULL,
    barcode_type text NOT NULL DEFAULT 'OTHER' CHECK (barcode_type IN ('EAN13', 'CODE128', 'UPC', 'INTERNAL', 'OTHER')),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, barcode),
    FOREIGN KEY (shop_id, product_id) REFERENCES products(shop_id, id) ON DELETE CASCADE
);
CREATE INDEX ix_product_barcodes_product ON product_barcodes (shop_id, product_id);

CREATE TABLE product_price_tiers (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    product_id uuid NOT NULL,
    tier_code text NOT NULL,
    unit_price_paise bigint NOT NULL CHECK (unit_price_paise >= 0),
    min_quantity_milli bigint NOT NULL DEFAULT 1000 CHECK (min_quantity_milli > 0),
    effective_from timestamptz NOT NULL DEFAULT now(),
    effective_to timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    FOREIGN KEY (shop_id, product_id) REFERENCES products(shop_id, id) ON DELETE CASCADE,
    CHECK (effective_to IS NULL OR effective_to > effective_from)
);

CREATE TABLE product_batches (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    product_id uuid NOT NULL,
    batch_number text NOT NULL,
    expiry_date date,
    purchase_date date,
    mrp_paise bigint CHECK (mrp_paise IS NULL OR mrp_paise >= 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, product_id, batch_number),
    FOREIGN KEY (shop_id, product_id) REFERENCES products(shop_id, id) ON DELETE CASCADE
);

CREATE INDEX ix_product_batches_expiry ON product_batches (shop_id, product_id, expiry_date) WHERE expiry_date IS NOT NULL;

CREATE TABLE product_serials (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    product_id uuid NOT NULL,
    batch_id uuid,
    serial_or_imei text NOT NULL,
    status text NOT NULL DEFAULT 'IN_STOCK' CHECK (status IN ('IN_STOCK', 'SOLD', 'RETURNED', 'DAMAGED', 'UNKNOWN')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, serial_or_imei),
    FOREIGN KEY (shop_id, product_id) REFERENCES products(shop_id, id) ON DELETE CASCADE,
    FOREIGN KEY (shop_id, batch_id) REFERENCES product_batches(shop_id, id)
);

-- ---------------------------------------------------------------------------
-- Customers, suppliers and document numbering
-- ---------------------------------------------------------------------------
CREATE TABLE parties (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    kind party_kind NOT NULL,
    name text NOT NULL,
    name_norm text NOT NULL,
    phone_e164 varchar(20),
    email text,
    gstin varchar(15),
    pan varchar(10),
    state_code char(2) REFERENCES states(code),
    billing_address jsonb NOT NULL DEFAULT '{}'::jsonb,
    shipping_address jsonb NOT NULL DEFAULT '{}'::jsonb,
    preferred_language varchar(5) NOT NULL DEFAULT 'en' CHECK (preferred_language IN ('en', 'hi', 'bn')),
    credit_limit_paise bigint CHECK (credit_limit_paise IS NULL OR credit_limit_paise >= 0),
    notes text,
    is_archived boolean NOT NULL DEFAULT false,
    hlc_physical_ms bigint NOT NULL DEFAULT 0,
    hlc_counter integer NOT NULL DEFAULT 0 CHECK (hlc_counter >= 0),
    hlc_node_id uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    CHECK (gstin IS NULL OR length(gstin) = 15)
);
CREATE INDEX ix_parties_name ON parties (shop_id, name_norm);
CREATE INDEX ix_parties_phone ON parties (shop_id, phone_e164) WHERE phone_e164 IS NOT NULL;
CREATE INDEX ix_parties_gstin ON parties (shop_id, gstin) WHERE gstin IS NOT NULL;

CREATE TABLE document_counters (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    device_id uuid NOT NULL,
    series varchar(16) NOT NULL,
    doc_type document_type NOT NULL,
    financial_year varchar(9) NOT NULL,
    next_sequence bigint NOT NULL DEFAULT 1 CHECK (next_sequence > 0),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, series, doc_type, financial_year),
    FOREIGN KEY (shop_id, device_id) REFERENCES devices(shop_id, id)
);

CREATE TABLE held_bills (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    device_id uuid NOT NULL,
    created_by_user_id uuid NOT NULL REFERENCES users(id),
    status text NOT NULL DEFAULT 'ACTIVE_DRAFT' CHECK (status IN ('ACTIVE_DRAFT', 'HELD')),
    customer_party_id uuid,
    label text,
    cart_snapshot jsonb NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT now(),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    FOREIGN KEY (shop_id, device_id) REFERENCES devices(shop_id, id),
    FOREIGN KEY (shop_id, customer_party_id) REFERENCES parties(shop_id, id)
);
CREATE INDEX ix_held_bills_device ON held_bills (shop_id, device_id, updated_at DESC);

-- ---------------------------------------------------------------------------
-- Invoices and immutable line snapshots
-- ---------------------------------------------------------------------------
CREATE TABLE invoices (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    location_id uuid,
    device_id uuid,
    created_by_user_id uuid REFERENCES users(id),
    party_id uuid,
    original_invoice_id uuid,
    doc_type document_type NOT NULL,
    status document_status NOT NULL DEFAULT 'DRAFT',
    series varchar(16) NOT NULL,
    financial_year varchar(9) NOT NULL,
    number varchar(16) NOT NULL,
    issue_at timestamptz,
    due_at timestamptz,
    customer_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,
    shop_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,
    customer_gstin_snapshot varchar(15),
    place_of_supply_state_code char(2) REFERENCES states(code),
    place_of_supply_override_reason text,
    tax_scheme_snapshot tax_scheme NOT NULL,
    gst_engine_version text NOT NULL,
    reference_bundle_version text NOT NULL,
    is_b2b boolean NOT NULL DEFAULT false,
    reverse_charge boolean NOT NULL DEFAULT false,
    subtotal_paise bigint NOT NULL DEFAULT 0 CHECK (subtotal_paise >= 0),
    line_discount_paise bigint NOT NULL DEFAULT 0 CHECK (line_discount_paise >= 0),
    invoice_discount_paise bigint NOT NULL DEFAULT 0 CHECK (invoice_discount_paise >= 0),
    taxable_value_paise bigint NOT NULL DEFAULT 0 CHECK (taxable_value_paise >= 0),
    cgst_paise bigint NOT NULL DEFAULT 0 CHECK (cgst_paise >= 0),
    sgst_paise bigint NOT NULL DEFAULT 0 CHECK (sgst_paise >= 0),
    utgst_paise bigint NOT NULL DEFAULT 0 CHECK (utgst_paise >= 0),
    igst_paise bigint NOT NULL DEFAULT 0 CHECK (igst_paise >= 0),
    cess_paise bigint NOT NULL DEFAULT 0 CHECK (cess_paise >= 0),
    round_off_paise bigint NOT NULL DEFAULT 0 CHECK (round_off_paise BETWEEN -50 AND 50),
    grand_total_paise bigint NOT NULL DEFAULT 0 CHECK (grand_total_paise >= 0),
    cancellation_reason text,
    cancelled_at timestamptz,
    cancelled_by_user_id uuid REFERENCES users(id),
    converted_to_invoice_id uuid,
    source_event_key text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, series, doc_type, financial_year, number),
    UNIQUE (shop_id, source_event_key),
    FOREIGN KEY (shop_id, location_id) REFERENCES shop_locations(shop_id, id),
    FOREIGN KEY (shop_id, device_id) REFERENCES devices(shop_id, id),
    FOREIGN KEY (shop_id, party_id) REFERENCES parties(shop_id, id),
    FOREIGN KEY (shop_id, original_invoice_id) REFERENCES invoices(shop_id, id),
    FOREIGN KEY (shop_id, converted_to_invoice_id) REFERENCES invoices(shop_id, id),
    CHECK (grand_total_paise = taxable_value_paise + cgst_paise + sgst_paise + utgst_paise + igst_paise + cess_paise + round_off_paise),
    CHECK (number <> '' AND length(number) <= 16),
    CHECK (status NOT IN ('FINALIZED', 'CANCELLED') OR issue_at IS NOT NULL),
    CHECK (status <> 'CANCELLED' OR (cancelled_at IS NOT NULL AND cancellation_reason IS NOT NULL)),
    CHECK (NOT is_b2b OR customer_gstin_snapshot IS NOT NULL)
);
CREATE INDEX ix_invoices_issue_date ON invoices (shop_id, issue_at DESC);
CREATE INDEX ix_invoices_party_date ON invoices (shop_id, party_id, issue_at DESC);
CREATE INDEX ix_invoices_type_status_date ON invoices (shop_id, doc_type, status, issue_at DESC);
CREATE INDEX ix_invoices_fy_series ON invoices (shop_id, financial_year, series, number);

CREATE TABLE invoice_lines (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    invoice_id uuid NOT NULL,
    line_number integer NOT NULL CHECK (line_number > 0),
    product_id uuid,
    original_invoice_line_id uuid,
    product_name_snapshot text NOT NULL,
    local_name_snapshot text,
    sku_snapshot text,
    barcode_snapshot text,
    hsn_code_snapshot varchar(8),
    tax_treatment_snapshot tax_treatment NOT NULL,
    unit_code_snapshot varchar(12) NOT NULL,
    quantity_milli bigint NOT NULL CHECK (quantity_milli > 0),
    unit_price_paise bigint NOT NULL CHECK (unit_price_paise >= 0),
    gross_line_paise bigint NOT NULL CHECK (gross_line_paise >= 0),
    tax_inclusive_snapshot boolean NOT NULL,
    gst_rate_bps integer NOT NULL CHECK (gst_rate_bps BETWEEN 0 AND 10000),
    cess_rate_bps integer NOT NULL DEFAULT 0 CHECK (cess_rate_bps BETWEEN 0 AND 10000),
    line_discount_paise bigint NOT NULL DEFAULT 0 CHECK (line_discount_paise >= 0),
    invoice_discount_alloc_paise bigint NOT NULL DEFAULT 0 CHECK (invoice_discount_alloc_paise >= 0),
    taxable_value_paise bigint NOT NULL CHECK (taxable_value_paise >= 0),
    cgst_paise bigint NOT NULL DEFAULT 0 CHECK (cgst_paise >= 0),
    sgst_paise bigint NOT NULL DEFAULT 0 CHECK (sgst_paise >= 0),
    utgst_paise bigint NOT NULL DEFAULT 0 CHECK (utgst_paise >= 0),
    igst_paise bigint NOT NULL DEFAULT 0 CHECK (igst_paise >= 0),
    cess_paise bigint NOT NULL DEFAULT 0 CHECK (cess_paise >= 0),
    line_total_paise bigint NOT NULL CHECK (line_total_paise >= 0),
    stock_disposition text CHECK (stock_disposition IS NULL OR stock_disposition IN ('RESTOCK', 'DAMAGED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, invoice_id, line_number),
    FOREIGN KEY (shop_id, invoice_id) REFERENCES invoices(shop_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (shop_id, product_id) REFERENCES products(shop_id, id),
    FOREIGN KEY (shop_id, original_invoice_line_id) REFERENCES invoice_lines(shop_id, id),
    CHECK (line_total_paise = taxable_value_paise + cgst_paise + sgst_paise + utgst_paise + igst_paise + cess_paise)
);
CREATE INDEX ix_invoice_lines_invoice ON invoice_lines (shop_id, invoice_id, line_number);
CREATE INDEX ix_invoice_lines_product ON invoice_lines (shop_id, product_id);

-- ---------------------------------------------------------------------------
-- Payments, payment allocations and purchase bills
-- ---------------------------------------------------------------------------
CREATE TABLE payments (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    invoice_id uuid,
    party_id uuid,
    device_id uuid,
    received_by_user_id uuid REFERENCES users(id),
    purpose payment_purpose NOT NULL,
    mode payment_mode NOT NULL,
    amount_paise bigint NOT NULL CHECK (amount_paise > 0),
    tendered_paise bigint CHECK (tendered_paise IS NULL OR tendered_paise >= 0),
    change_paise bigint NOT NULL DEFAULT 0 CHECK (change_paise >= 0),
    provider_reference text,
    reverses_payment_id uuid,
    occurred_at timestamptz NOT NULL,
    source_event_key text NOT NULL,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, source_event_key),
    FOREIGN KEY (shop_id, invoice_id) REFERENCES invoices(shop_id, id),
    FOREIGN KEY (shop_id, party_id) REFERENCES parties(shop_id, id),
    FOREIGN KEY (shop_id, device_id) REFERENCES devices(shop_id, id),
    FOREIGN KEY (shop_id, reverses_payment_id) REFERENCES payments(shop_id, id)
);
CREATE INDEX ix_payments_invoice ON payments (shop_id, invoice_id, occurred_at DESC);
CREATE INDEX ix_payments_party ON payments (shop_id, party_id, occurred_at DESC);

CREATE TABLE payment_allocations (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    payment_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    amount_paise bigint NOT NULL CHECK (amount_paise > 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, payment_id, invoice_id),
    FOREIGN KEY (shop_id, payment_id) REFERENCES payments(shop_id, id),
    FOREIGN KEY (shop_id, invoice_id) REFERENCES invoices(shop_id, id)
);

CREATE TABLE purchase_bills (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    location_id uuid,
    device_id uuid,
    supplier_party_id uuid NOT NULL,
    supplier_invoice_number text NOT NULL,
    supplier_invoice_date date NOT NULL,
    status purchase_status NOT NULL DEFAULT 'DRAFT',
    supplier_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,
    taxable_value_paise bigint NOT NULL DEFAULT 0 CHECK (taxable_value_paise >= 0),
    cgst_paise bigint NOT NULL DEFAULT 0 CHECK (cgst_paise >= 0),
    sgst_paise bigint NOT NULL DEFAULT 0 CHECK (sgst_paise >= 0),
    utgst_paise bigint NOT NULL DEFAULT 0 CHECK (utgst_paise >= 0),
    igst_paise bigint NOT NULL DEFAULT 0 CHECK (igst_paise >= 0),
    cess_paise bigint NOT NULL DEFAULT 0 CHECK (cess_paise >= 0),
    total_paise bigint NOT NULL DEFAULT 0 CHECK (total_paise >= 0),
    received_at timestamptz,
    cancellation_reason text,
    source_event_key text NOT NULL,
    created_by_user_id uuid REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, supplier_party_id, supplier_invoice_number),
    UNIQUE (shop_id, source_event_key),
    FOREIGN KEY (shop_id, location_id) REFERENCES shop_locations(shop_id, id),
    FOREIGN KEY (shop_id, device_id) REFERENCES devices(shop_id, id),
    FOREIGN KEY (shop_id, supplier_party_id) REFERENCES parties(shop_id, id),
    CHECK (total_paise = taxable_value_paise + cgst_paise + sgst_paise + utgst_paise + igst_paise + cess_paise)
);
CREATE INDEX ix_purchase_bills_date ON purchase_bills (shop_id, supplier_invoice_date DESC);

CREATE TABLE purchase_lines (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    purchase_bill_id uuid NOT NULL,
    line_number integer NOT NULL CHECK (line_number > 0),
    product_id uuid,
    product_name_snapshot text NOT NULL,
    hsn_code_snapshot varchar(8),
    unit_code_snapshot varchar(12) NOT NULL,
    quantity_milli bigint NOT NULL CHECK (quantity_milli > 0),
    unit_cost_paise bigint NOT NULL CHECK (unit_cost_paise >= 0),
    gst_rate_bps integer NOT NULL DEFAULT 0 CHECK (gst_rate_bps BETWEEN 0 AND 10000),
    cess_rate_bps integer NOT NULL DEFAULT 0 CHECK (cess_rate_bps BETWEEN 0 AND 10000),
    taxable_value_paise bigint NOT NULL CHECK (taxable_value_paise >= 0),
    cgst_paise bigint NOT NULL DEFAULT 0 CHECK (cgst_paise >= 0),
    sgst_paise bigint NOT NULL DEFAULT 0 CHECK (sgst_paise >= 0),
    utgst_paise bigint NOT NULL DEFAULT 0 CHECK (utgst_paise >= 0),
    igst_paise bigint NOT NULL DEFAULT 0 CHECK (igst_paise >= 0),
    cess_paise bigint NOT NULL DEFAULT 0 CHECK (cess_paise >= 0),
    line_total_paise bigint NOT NULL CHECK (line_total_paise >= 0),
    batch_id uuid,
    expiry_date date,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, purchase_bill_id, line_number),
    FOREIGN KEY (shop_id, purchase_bill_id) REFERENCES purchase_bills(shop_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (shop_id, product_id) REFERENCES products(shop_id, id),
    FOREIGN KEY (shop_id, batch_id) REFERENCES product_batches(shop_id, id),
    CHECK (line_total_paise = taxable_value_paise + cgst_paise + sgst_paise + utgst_paise + igst_paise + cess_paise)
);

-- ---------------------------------------------------------------------------
-- Append-only inventory, derived stock levels and party ledger
-- ---------------------------------------------------------------------------
CREATE TABLE stock_movements (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    location_id uuid NOT NULL,
    product_id uuid NOT NULL,
    batch_id uuid,
    serial_id uuid,
    movement_type stock_movement_type NOT NULL,
    quantity_delta_milli bigint NOT NULL CHECK (quantity_delta_milli <> 0),
    unit_cost_paise bigint CHECK (unit_cost_paise IS NULL OR unit_cost_paise >= 0),
    invoice_id uuid,
    invoice_line_id uuid,
    purchase_bill_id uuid,
    purchase_line_id uuid,
    reason_code text,
    reason_note text,
    device_id uuid,
    created_by_user_id uuid REFERENCES users(id),
    occurred_at timestamptz NOT NULL,
    source_event_key text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, source_event_key),
    FOREIGN KEY (shop_id, location_id) REFERENCES shop_locations(shop_id, id),
    FOREIGN KEY (shop_id, product_id) REFERENCES products(shop_id, id),
    FOREIGN KEY (shop_id, batch_id) REFERENCES product_batches(shop_id, id),
    FOREIGN KEY (shop_id, serial_id) REFERENCES product_serials(shop_id, id),
    FOREIGN KEY (shop_id, invoice_id) REFERENCES invoices(shop_id, id),
    FOREIGN KEY (shop_id, invoice_line_id) REFERENCES invoice_lines(shop_id, id),
    FOREIGN KEY (shop_id, purchase_bill_id) REFERENCES purchase_bills(shop_id, id),
    FOREIGN KEY (shop_id, purchase_line_id) REFERENCES purchase_lines(shop_id, id),
    FOREIGN KEY (shop_id, device_id) REFERENCES devices(shop_id, id)
);
CREATE INDEX ix_stock_movements_product_time ON stock_movements (shop_id, product_id, occurred_at DESC);
CREATE INDEX ix_stock_movements_location_time ON stock_movements (shop_id, location_id, occurred_at DESC);
CREATE INDEX ix_stock_movements_invoice ON stock_movements (shop_id, invoice_id) WHERE invoice_id IS NOT NULL;

CREATE TABLE stock_levels (
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    location_id uuid NOT NULL,
    product_id uuid NOT NULL,
    quantity_on_hand_milli bigint NOT NULL DEFAULT 0,
    quantity_reserved_milli bigint NOT NULL DEFAULT 0 CHECK (quantity_reserved_milli >= 0),
    quantity_sellable_milli bigint GENERATED ALWAYS AS (quantity_on_hand_milli - quantity_reserved_milli) STORED,
    rebuilt_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (shop_id, location_id, product_id),
    FOREIGN KEY (shop_id, location_id) REFERENCES shop_locations(shop_id, id),
    FOREIGN KEY (shop_id, product_id) REFERENCES products(shop_id, id)
);
CREATE INDEX ix_stock_levels_low_stock ON stock_levels (shop_id, quantity_sellable_milli);

CREATE TABLE ledger_entries (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    party_id uuid NOT NULL,
    side ledger_side NOT NULL,
    amount_paise bigint NOT NULL CHECK (amount_paise > 0),
    occurred_at timestamptz NOT NULL,
    invoice_id uuid,
    payment_id uuid,
    purchase_bill_id uuid,
    reference_text text,
    memo text,
    source_event_key text NOT NULL,
    created_by_user_id uuid REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, source_event_key),
    FOREIGN KEY (shop_id, party_id) REFERENCES parties(shop_id, id),
    FOREIGN KEY (shop_id, invoice_id) REFERENCES invoices(shop_id, id),
    FOREIGN KEY (shop_id, payment_id) REFERENCES payments(shop_id, id),
    FOREIGN KEY (shop_id, purchase_bill_id) REFERENCES purchase_bills(shop_id, id)
);
CREATE INDEX ix_ledger_party_time ON ledger_entries (shop_id, party_id, occurred_at DESC, id);
CREATE INDEX ix_ledger_invoice ON ledger_entries (shop_id, invoice_id) WHERE invoice_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Day close and tamper-evident audit log
-- ---------------------------------------------------------------------------
CREATE TABLE day_close_sessions (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    location_id uuid,
    business_date date NOT NULL,
    opened_by_user_id uuid REFERENCES users(id),
    closed_by_user_id uuid REFERENCES users(id),
    opening_cash_paise bigint NOT NULL DEFAULT 0,
    cash_sales_paise bigint NOT NULL DEFAULT 0,
    customer_cash_receipts_paise bigint NOT NULL DEFAULT 0,
    cash_refunds_paise bigint NOT NULL DEFAULT 0,
    cash_expenses_paise bigint NOT NULL DEFAULT 0,
    expected_cash_paise bigint NOT NULL DEFAULT 0,
    actual_cash_paise bigint,
    cash_variance_paise bigint,
    upi_bank_total_paise bigint NOT NULL DEFAULT 0,
    new_credit_paise bigint NOT NULL DEFAULT 0,
    notes text,
    closed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, location_id, business_date),
    FOREIGN KEY (shop_id, location_id) REFERENCES shop_locations(shop_id, id),
    CHECK (actual_cash_paise IS NULL OR actual_cash_paise >= 0)
);

CREATE TABLE audit_chain_heads (
    shop_id uuid PRIMARY KEY REFERENCES shops(id) ON DELETE CASCADE,
    last_sequence bigint NOT NULL DEFAULT 0 CHECK (last_sequence >= 0),
    last_hash bytea,
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (last_hash IS NULL OR octet_length(last_hash) = 32)
);

CREATE TABLE audit_log (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    chain_sequence bigint NOT NULL CHECK (chain_sequence > 0),
    actor_user_id uuid REFERENCES users(id),
    device_id uuid,
    action text NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid,
    reason text,
    before_snapshot jsonb,
    after_snapshot jsonb,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    previous_hash bytea,
    event_hash bytea NOT NULL CHECK (octet_length(event_hash) = 32),
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, chain_sequence),
    FOREIGN KEY (shop_id, device_id) REFERENCES devices(shop_id, id),
    CHECK (previous_hash IS NULL OR octet_length(previous_hash) = 32)
);
CREATE INDEX ix_audit_log_entity ON audit_log (shop_id, entity_type, entity_id, chain_sequence DESC);
CREATE INDEX ix_audit_log_time ON audit_log (shop_id, occurred_at DESC);

-- ---------------------------------------------------------------------------
-- Offline sync: idempotent transaction bundles and ordered pull change log
-- ---------------------------------------------------------------------------
CREATE TABLE sync_bundles (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    device_id uuid NOT NULL,
    client_bundle_id uuid NOT NULL,
    payload_sha256 bytea NOT NULL CHECK (octet_length(payload_sha256) = 32),
    status sync_bundle_status NOT NULL DEFAULT 'RECEIVED',
    result jsonb NOT NULL DEFAULT '{}'::jsonb,
    received_at timestamptz NOT NULL DEFAULT now(),
    applied_at timestamptz,
    error_code text,
    error_detail text,
    UNIQUE (shop_id, id),
    UNIQUE (shop_id, device_id, client_bundle_id),
    FOREIGN KEY (shop_id, device_id) REFERENCES devices(shop_id, id)
);

CREATE TABLE sync_change_log (
    cursor_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    bundle_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    operation text NOT NULL CHECK (operation IN ('UPSERT', 'TOMBSTONE', 'APPEND')),
    payload jsonb NOT NULL,
    hlc_physical_ms bigint NOT NULL DEFAULT 0,
    hlc_counter integer NOT NULL DEFAULT 0 CHECK (hlc_counter >= 0),
    hlc_node_id uuid,
    received_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, operation_id),
    FOREIGN KEY (shop_id, bundle_id) REFERENCES sync_bundles(shop_id, id)
);
CREATE INDEX ix_sync_change_pull ON sync_change_log (shop_id, cursor_id);

-- ---------------------------------------------------------------------------
-- Backups, report jobs/files/schedules and worker operations
-- ---------------------------------------------------------------------------
CREATE TABLE backups (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    created_by_user_id uuid REFERENCES users(id),
    device_id uuid,
    status backup_status NOT NULL DEFAULT 'UPLOADING',
    object_key text NOT NULL,
    size_bytes bigint CHECK (size_bytes IS NULL OR size_bytes >= 0),
    sha256 bytea CHECK (sha256 IS NULL OR octet_length(sha256) = 32),
    encrypted boolean NOT NULL DEFAULT true,
    encryption_algorithm text NOT NULL DEFAULT 'AES-256-GCM',
    format_version text NOT NULL,
    uploaded_at timestamptz,
    expires_at timestamptz,
    deleted_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (object_key),
    FOREIGN KEY (shop_id, device_id) REFERENCES devices(shop_id, id)
);
CREATE INDEX ix_backups_shop_time ON backups (shop_id, created_at DESC);

CREATE TABLE report_jobs (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    requested_by_user_id uuid REFERENCES users(id),
    report_type text NOT NULL,
    output_format report_format NOT NULL DEFAULT 'XLSX',
    parameters jsonb NOT NULL DEFAULT '{}'::jsonb,
    status report_job_status NOT NULL DEFAULT 'QUEUED',
    progress_percent smallint NOT NULL DEFAULT 0 CHECK (progress_percent BETWEEN 0 AND 100),
    error_code text,
    error_detail text,
    requested_at timestamptz NOT NULL DEFAULT now(),
    started_at timestamptz,
    completed_at timestamptz,
    UNIQUE (shop_id, id)
);
CREATE INDEX ix_report_jobs_queue ON report_jobs (status, requested_at) WHERE status = 'QUEUED';
CREATE INDEX ix_report_jobs_shop_time ON report_jobs (shop_id, requested_at DESC);

CREATE TABLE report_schedules (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    created_by_user_id uuid REFERENCES users(id),
    report_type text NOT NULL,
    output_format report_format NOT NULL DEFAULT 'XLSX',
    parameters jsonb NOT NULL DEFAULT '{}'::jsonb,
    cron_expression text NOT NULL,
    timezone text NOT NULL DEFAULT 'Asia/Kolkata',
    delivery_channels message_channel[] NOT NULL DEFAULT ARRAY[]::message_channel[],
    recipient_config jsonb NOT NULL DEFAULT '{}'::jsonb,
    is_enabled boolean NOT NULL DEFAULT true,
    next_run_at timestamptz,
    last_run_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id)
);
CREATE INDEX ix_report_schedules_due ON report_schedules (next_run_at) WHERE is_enabled;

CREATE TABLE report_files (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    report_job_id uuid NOT NULL,
    object_key text NOT NULL,
    output_format report_format NOT NULL,
    size_bytes bigint CHECK (size_bytes IS NULL OR size_bytes >= 0),
    sha256 bytea CHECK (sha256 IS NULL OR octet_length(sha256) = 32),
    generated_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    deleted_at timestamptz,
    UNIQUE (shop_id, id),
    UNIQUE (object_key),
    FOREIGN KEY (shop_id, report_job_id) REFERENCES report_jobs(shop_id, id)
);
CREATE INDEX ix_report_files_expiry ON report_files (expires_at) WHERE deleted_at IS NULL;

CREATE TABLE worker_jobs (
    id uuid PRIMARY KEY,
    shop_id uuid REFERENCES shops(id) ON DELETE CASCADE,
    job_type text NOT NULL,
    deduplication_key text NOT NULL,
    payload jsonb NOT NULL DEFAULT '{}'::jsonb,
    status worker_job_status NOT NULL DEFAULT 'QUEUED',
    attempt_count smallint NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    max_attempts smallint NOT NULL DEFAULT 3 CHECK (max_attempts > 0),
    run_after timestamptz NOT NULL DEFAULT now(),
    locked_at timestamptz,
    locked_by text,
    last_error text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX uq_worker_job_shop_dedupe ON worker_jobs (shop_id, job_type, deduplication_key) WHERE shop_id IS NOT NULL;
CREATE UNIQUE INDEX uq_worker_job_global_dedupe ON worker_jobs (job_type, deduplication_key) WHERE shop_id IS NULL;
CREATE INDEX ix_worker_jobs_due ON worker_jobs (run_after) WHERE status = 'QUEUED';

CREATE TABLE worker_job_runs (
    id uuid PRIMARY KEY,
    job_id uuid NOT NULL REFERENCES worker_jobs(id) ON DELETE CASCADE,
    attempt_number smallint NOT NULL CHECK (attempt_number > 0),
    started_at timestamptz NOT NULL,
    finished_at timestamptz,
    succeeded boolean,
    error_detail text,
    worker_id text,
    UNIQUE (job_id, attempt_number)
);

CREATE TABLE dead_letter_jobs (
    id uuid PRIMARY KEY,
    original_job_id uuid REFERENCES worker_jobs(id),
    shop_id uuid REFERENCES shops(id) ON DELETE CASCADE,
    job_type text NOT NULL,
    payload jsonb NOT NULL,
    final_error text NOT NULL,
    attempts smallint NOT NULL,
    moved_at timestamptz NOT NULL DEFAULT now(),
    resolved_at timestamptz,
    resolution_note text
);

-- ---------------------------------------------------------------------------
-- Phase 2 messaging, consents, assistant, purchase OCR and data-rights workflows
-- ---------------------------------------------------------------------------
CREATE TABLE notification_consents (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    party_id uuid NOT NULL,
    channel message_channel NOT NULL,
    status consent_status NOT NULL,
    purpose text NOT NULL,
    captured_by_user_id uuid REFERENCES users(id),
    evidence jsonb NOT NULL DEFAULT '{}'::jsonb,
    granted_at timestamptz,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    FOREIGN KEY (shop_id, party_id) REFERENCES parties(shop_id, id)
);
CREATE INDEX ix_notification_consent_current ON notification_consents (shop_id, party_id, channel, created_at DESC);

CREATE TABLE messages (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    party_id uuid,
    channel message_channel NOT NULL,
    template_code text,
    destination_masked text,
    body_text text NOT NULL,
    status message_status NOT NULL DEFAULT 'QUEUED',
    provider_message_id text,
    consent_id uuid,
    related_invoice_id uuid,
    related_report_file_id uuid,
    queued_at timestamptz NOT NULL DEFAULT now(),
    sent_at timestamptz,
    delivered_at timestamptz,
    failed_at timestamptz,
    failure_code text,
    failure_detail text,
    UNIQUE (shop_id, id),
    FOREIGN KEY (shop_id, party_id) REFERENCES parties(shop_id, id),
    FOREIGN KEY (shop_id, consent_id) REFERENCES notification_consents(shop_id, id),
    FOREIGN KEY (shop_id, related_invoice_id) REFERENCES invoices(shop_id, id),
    FOREIGN KEY (shop_id, related_report_file_id) REFERENCES report_files(shop_id, id)
);
CREATE INDEX ix_messages_shop_time ON messages (shop_id, queued_at DESC);

CREATE TABLE assistant_conversations (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES users(id),
    language_code varchar(5) NOT NULL DEFAULT 'en' CHECK (language_code IN ('en', 'hi', 'bn')),
    created_at timestamptz NOT NULL DEFAULT now(),
    last_message_at timestamptz,
    retention_until timestamptz,
    UNIQUE (shop_id, id)
);

CREATE TABLE assistant_messages (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    conversation_id uuid NOT NULL,
    role text NOT NULL CHECK (role IN ('USER', 'ASSISTANT', 'TOOL')),
    content text NOT NULL,
    tool_name text,
    grounded_result jsonb,
    grounding_verified boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    FOREIGN KEY (shop_id, conversation_id) REFERENCES assistant_conversations(shop_id, id) ON DELETE CASCADE
);
CREATE INDEX ix_assistant_messages_conversation ON assistant_messages (shop_id, conversation_id, created_at);

CREATE TABLE purchase_attachments (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    purchase_bill_id uuid,
    uploaded_by_user_id uuid REFERENCES users(id),
    object_key text NOT NULL,
    media_type text NOT NULL,
    size_bytes bigint NOT NULL CHECK (size_bytes >= 0 AND size_bytes <= 10485760),
    sha256 bytea NOT NULL CHECK (octet_length(sha256) = 32),
    ocr_status text NOT NULL DEFAULT 'PENDING' CHECK (ocr_status IN ('PENDING', 'PROCESSING', 'DRAFT_READY', 'FAILED', 'CONFIRMED')),
    ocr_draft jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    UNIQUE (object_key),
    FOREIGN KEY (shop_id, purchase_bill_id) REFERENCES purchase_bills(shop_id, id)
);

CREATE TABLE data_requests (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    requested_by_user_id uuid NOT NULL REFERENCES users(id),
    request_type data_request_type NOT NULL,
    status data_request_status NOT NULL DEFAULT 'PENDING',
    reason text,
    output_object_key text,
    requested_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    expires_at timestamptz,
    failure_detail text,
    UNIQUE (shop_id, id),
    UNIQUE (output_object_key)
);

-- ---------------------------------------------------------------------------
-- Phase 3 compliance adapters and payment-provider webhook idempotency
-- ---------------------------------------------------------------------------
CREATE TABLE compliance_submissions (
    id uuid PRIMARY KEY,
    shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    invoice_id uuid NOT NULL,
    compliance_kind compliance_kind NOT NULL,
    provider_code text NOT NULL,
    status compliance_status NOT NULL DEFAULT 'DRAFT',
    request_payload jsonb NOT NULL,
    response_payload jsonb,
    external_reference text,
    irn text,
    acknowledgement_number text,
    acknowledgement_at timestamptz,
    qr_payload text,
    error_code text,
    error_detail text,
    submitted_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (shop_id, id),
    FOREIGN KEY (shop_id, invoice_id) REFERENCES invoices(shop_id, id)
);
CREATE INDEX ix_compliance_invoice ON compliance_submissions (shop_id, invoice_id, created_at DESC);

CREATE TABLE payment_webhook_events (
    id uuid PRIMARY KEY,
    shop_id uuid REFERENCES shops(id) ON DELETE CASCADE,
    provider_code text NOT NULL,
    provider_event_id text NOT NULL,
    payload_sha256 bytea NOT NULL CHECK (octet_length(payload_sha256) = 32),
    payload jsonb NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    processing_error text,
    UNIQUE (provider_code, provider_event_id)
);

-- ---------------------------------------------------------------------------
-- Append-only / immutability guards
-- ---------------------------------------------------------------------------
CREATE FUNCTION shopbill_reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'append-only record in % cannot be updated or deleted', TG_TABLE_NAME
        USING ERRCODE = '55000';
END;
$$;

CREATE TRIGGER trg_payments_append_only BEFORE UPDATE OR DELETE ON payments
FOR EACH ROW EXECUTE FUNCTION shopbill_reject_mutation();
CREATE TRIGGER trg_payment_allocations_append_only BEFORE UPDATE OR DELETE ON payment_allocations
FOR EACH ROW EXECUTE FUNCTION shopbill_reject_mutation();
CREATE TRIGGER trg_stock_movements_append_only BEFORE UPDATE OR DELETE ON stock_movements
FOR EACH ROW EXECUTE FUNCTION shopbill_reject_mutation();
CREATE TRIGGER trg_ledger_entries_append_only BEFORE UPDATE OR DELETE ON ledger_entries
FOR EACH ROW EXECUTE FUNCTION shopbill_reject_mutation();
CREATE TRIGGER trg_audit_log_append_only BEFORE UPDATE OR DELETE ON audit_log
FOR EACH ROW EXECUTE FUNCTION shopbill_reject_mutation();
CREATE TRIGGER trg_sync_change_log_append_only BEFORE UPDATE OR DELETE ON sync_change_log
FOR EACH ROW EXECUTE FUNCTION shopbill_reject_mutation();
CREATE TRIGGER trg_webhook_events_append_only BEFORE UPDATE OR DELETE ON payment_webhook_events
FOR EACH ROW EXECUTE FUNCTION shopbill_reject_mutation();

CREATE FUNCTION shopbill_guard_finalized_invoice() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.status IN ('FINALIZED', 'CANCELLED') THEN
            RAISE EXCEPTION 'finalized invoices cannot be deleted; issue a credit/debit note or cancel with a reason'
                USING ERRCODE = '55000';
        END IF;
        RETURN OLD;
    END IF;

    IF OLD.status = 'CANCELLED' THEN
        RAISE EXCEPTION 'cancelled invoices are immutable'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.status = 'FINALIZED' THEN
        IF NEW.status NOT IN ('FINALIZED', 'CANCELLED') THEN
            RAISE EXCEPTION 'a finalized invoice cannot return to a draft or another status'
                USING ERRCODE = '55000';
        END IF;
        IF (to_jsonb(NEW) - ARRAY['status', 'cancelled_at', 'cancelled_by_user_id', 'cancellation_reason', 'updated_at']) IS DISTINCT FROM
           (to_jsonb(OLD) - ARRAY['status', 'cancelled_at', 'cancelled_by_user_id', 'cancellation_reason', 'updated_at']) THEN
            RAISE EXCEPTION 'finalized invoice financial and identity fields are immutable'
                USING ERRCODE = '55000';
        END IF;
        IF NEW.status = 'FINALIZED' AND
           (NEW.cancelled_at IS DISTINCT FROM OLD.cancelled_at OR
            NEW.cancelled_by_user_id IS DISTINCT FROM OLD.cancelled_by_user_id OR
            NEW.cancellation_reason IS DISTINCT FROM OLD.cancellation_reason) THEN
            RAISE EXCEPTION 'cancellation fields may only change when cancelling a finalized invoice'
                USING ERRCODE = '55000';
        END IF;
        IF NEW.status = 'CANCELLED' AND
           (NEW.cancelled_at IS NULL OR NEW.cancellation_reason IS NULL OR btrim(NEW.cancellation_reason) = '') THEN
            RAISE EXCEPTION 'cancellation requires a timestamp and reason'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_invoice_immutable BEFORE UPDATE OR DELETE ON invoices
FOR EACH ROW EXECUTE FUNCTION shopbill_guard_finalized_invoice();

CREATE FUNCTION shopbill_guard_finalized_invoice_line() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    old_parent_status document_status;
    new_parent_status document_status;
BEGIN
    SELECT status INTO old_parent_status FROM invoices WHERE shop_id = OLD.shop_id AND id = OLD.invoice_id;
    IF TG_OP = 'UPDATE' THEN
        SELECT status INTO new_parent_status FROM invoices WHERE shop_id = NEW.shop_id AND id = NEW.invoice_id;
    ELSE
        new_parent_status := old_parent_status;
    END IF;
    IF old_parent_status IN ('FINALIZED', 'CANCELLED') OR new_parent_status IN ('FINALIZED', 'CANCELLED') THEN
        RAISE EXCEPTION 'lines of a finalized invoice are immutable'
            USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_invoice_lines_immutable BEFORE UPDATE OR DELETE ON invoice_lines
FOR EACH ROW EXECUTE FUNCTION shopbill_guard_finalized_invoice_line();

-- ---------------------------------------------------------------------------
-- Tenant isolation with PostgreSQL Row-Level Security (defence in depth)
-- API must SET LOCAL app.shop_id = '<authorized shop UUID>' per transaction.
-- Reference/catalog tables without shop_id are global and intentionally not RLS-scoped.
-- ---------------------------------------------------------------------------
ALTER TABLE shops ENABLE ROW LEVEL SECURITY;
ALTER TABLE shops FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON shops
    USING (id = NULLIF(current_setting('app.shop_id', true), '')::uuid)
    WITH CHECK (id = NULLIF(current_setting('app.shop_id', true), '')::uuid);

DO $$
DECLARE
    t text;
    tenant_tables text[] := ARRAY[
        'roles', 'role_permissions', 'shop_memberships', 'shop_locations', 'devices',
        'refresh_token_families', 'refresh_tokens', 'product_categories', 'brands', 'units',
        'products', 'product_barcodes', 'product_price_tiers', 'product_batches', 'product_serials',
        'parties', 'document_counters', 'held_bills', 'invoices', 'invoice_lines', 'payments',
        'payment_allocations', 'purchase_bills', 'purchase_lines', 'stock_movements', 'stock_levels',
        'ledger_entries', 'day_close_sessions', 'audit_chain_heads', 'audit_log', 'sync_bundles',
        'sync_change_log', 'backups', 'report_jobs', 'report_schedules', 'report_files', 'messages',
        'notification_consents', 'assistant_conversations', 'assistant_messages', 'purchase_attachments',
        'data_requests', 'compliance_submissions'
    ];
BEGIN
    FOREACH t IN ARRAY tenant_tables LOOP
        EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format(
            'CREATE POLICY tenant_isolation ON %I USING (shop_id = NULLIF(current_setting(''app.shop_id'', true), '''')::uuid) WITH CHECK (shop_id = NULLIF(current_setting(''app.shop_id'', true), '''')::uuid)',
            t
        );
    END LOOP;
END $$;

COMMIT;

